def build_html() -> str:
    html = zlib.decompress(base64.b64decode("".join(_PAYLOAD.split()))).decode("utf-8")
    html = html.replace('name:"HIS NAME"', f'name:{_js(HIS_NAME)}')
    html = html.replace('nickname:"Handsome"', f'nickname:{_js(NICKNAME)}')
    html = html.replace('senderName:"YOUR NAME"', f'senderName:{_js(YOUR_NAME)}')
    html = html.replace('datePlace:"YOUR DREAM DATE PLACE"', f'datePlace:{_js(DATE_PLACE)}')
    photo = Path(__file__).with_name(PHOTO_FILE)
    if photo.exists():
        mime = "image/png" if photo.suffix.lower() == ".png" else "image/jpeg"
        data = base64.b64encode(photo.read_bytes()).decode()
        html = html.replace('"/images/us.jpg"', f'"data:{mime};base64,{data}"')
    if MUSIC_URL:
        html = html.replace('"/music/romantic-song.mp3"', _js(MUSIC_URL))
    return html


def _js(s: str) -> str:
    import json
    return json.dumps(s, ensure_ascii=False)


components.html(build_html(), height=800, scrolling=True)
